# src/code_visualizer/tools/indexing/constants.py
"""Shared constants for the indexing pipeline."""

# Maximum AST traversal depth before skipping a branch.
# Prevents RecursionError on deeply nested or autogenerated source files.
MAX_AST_DEPTH = 200

DEFAULT_IGNORE_PATTERNS = [
    "node_modules/",
    "venv/",
    ".venv/",
    "env/",
    ".env/",
    "dist/",
    "build/",
    "target/",
    "out/",
    # .NET intermediate output: contains *generated* source (AssemblyInfo.cs,
    # GlobalUsings.g.cs) that pollutes the graph with phantom modules (#1585).
    "obj/",
    # Terraform and Terragrunt vendor a copy of every remote module into these after `init`,
    # the same way node_modules works: 23,000 vendored files against 1,900 real ones on one
    # estate, all of them merging into the same global Module namespace.
    ".terraform/",
    ".terragrunt-cache/",
    # .terraform.lock.hcl, written by `init` next to every root module: provider hashes, not
    # code, whose `provider "registry.terraform.io/..."` blocks would otherwise index as one
    # Class per stack.
    "*.lock.hcl",
    ".git/",
    ".code-visualizer/",
    "__pycache__/",
    "*.png",
    "*.jpg",
    "*.jpeg",
    "*.gif",
    "*.svg",
    "*.mp4",
    "*.mp3",
    "*.zip",
    "*.tar",
    "*.gz",
    # Style sheets: the CSS parser makes a node of every rule (a vendored
    # swagger-ui.css gave 6,000), which crowds the graph and the search with
    # selectors. `!*.css` in .cvizignore brings them back.
    "*.css",
    "*.scss",
    "*.sass",
    "*.less",
    "*.styl",
    "*.pcss",
    "*.postcss",
    # Minified bundles and source maps: generated, not read.
    "*.min.js",
    "*.min.css",
    "*.map",
]
